// clone returns a concrete clone of the WarehouseQuery for internal use by First/Only.
func (q *WarehouseQuery) clone() *WarehouseQuery {
	if q == nil {
		return nil
	}
	c := &WarehouseQuery{
		config:     q.config,
		ctx:        q.ctx.Clone(),
		inters:     q.inters,
		modifiers:  runtime.CloneSlice(q.modifiers),
		order:      runtime.CloneSlice(q.order),
		path:       q.path,
		predicates: runtime.CloneSlice(q.predicates),
		withOrders: q.withOrders.clone(),
		withStocks: q.withStocks.clone(),
	}
	if q.withNamedStocks != nil {
		c.withNamedStocks = make(map[string]*StockQuery, len(q.withNamedStocks))
		for name, q := range q.withNamedStocks {
			c.withNamedStocks[name] = q.clone()
		}
	}
	if q.withNamedOrders != nil {
		c.withNamedOrders = make(map[string]*OrderQuery, len(q.withNamedOrders))
		for name, q := range q.withNamedOrders {
			c.withNamedOrders[name] = q.clone()
		}
	}
	return c
}

// loadStocks eagerly loads the "stocks" edge for the given nodes.
func (q *WarehouseQuery) loadStocks(ctx context.Context, query *StockQuery, nodes []*entity.Warehouse, init func(*entity.Warehouse), assign func(*entity.Warehouse, *entity.Stock)) error {
	query = query.clone()
	fks := make([]any, 0, len(nodes))
	nodeids := make(map[int]*entity.Warehouse, len(nodes))
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	query.withFKs = true
	query.Where(func(s *sql.Selector) {
		s.Where(sql.In(s.C(warehouse.StocksColumn), fks...))
	})
	limit, err := runtime.PlanPerParentLimit[int](ctx, query.ctx, query.config.Driver, "stocks")
	if err != nil {
		return err
	}
	if limit.Active {
		query.modifiers = append(query.modifiers, func(s *sql.Selector) {
			limit.Apply(s, s.C(warehouse.StocksColumn), s.C(stock.FieldID))
		})
	}
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.FKValue("warehouse_stocks")
		if fk == nil {
			return fmt.Errorf("velox: foreign-key %q is nil for node %v", "warehouse_stocks", n.ID)
		}
		parentID := derefFK(fk).(int)
		node, ok := nodeids[parentID]
		if !ok {
			return fmt.Errorf("velox: unexpected foreign-key %q returned %v for node %v", "warehouse_stocks", parentID, n.ID)
		}
		if !limit.Keep(parentID) {
			continue
		}
		assign(node, n)
	}
	return nil
}

